ronmentConfirmation';DeltaVolumes='Export-WsmArtifactDeltaVolumes';DeltaVolumeImport='Import-WsmArtifactDeltaVolumes';LabReport='Export-WsmLabValidationReport';ConfigReview='Export-WsmConfigArtifactReview';ConfigScopeDraft='Export-WsmConfigArtifactScopeDraft';DeltaManifest='New-WsmArtifactDeltaManifest';DeltaCheck='Test-WsmArtifactDeltaManifest';DeltaZip='Export-WsmArtifactDeltaZip';DeltaImport='Import-WsmArtifactDeltaZip';DeltaRestore='Invoke-WsmArtifactDeltaRestore';DeltaRepair='Repair-WsmArtifactDeltaRestore';CancellationToken='New-WsmCancellationToken';RequestCancellation='Request-WsmCancellation';GroupPlan='New-WsmConsistencyGroupPlan';GroupReceipt='New-WsmConsistencyGroupReceipt';GroupBarrier='Assert-WsmConsistencyGroupBarrier';RollbackResult='Export-WsmRollbackResult';QualificationKey='Get-WsmQualificationRecordKey';QualificationRecord='New-WsmQualificationRecord';QualificationAdd='Add-WsmQualification';QualificationRevoke='Revoke-WsmQualification';QualificationLookup='Resolve-WsmProductionQualification';QualificationMatrix='Get-WsmQualificationMatrix';SourceTaskTemplate='Export-WsmSourceTaskReconciliationTemplate';SourceResume='Invoke-WsmSourceResume';SpecBundleExport='Export-WsmMigrationSpecBundle';SpecBundlePreview='Get-WsmMigrationSpecBundlePreview';SpecBundleImport='Import-WsmMigrationSpecBundle';RepairWorkspace='Repair-WsmWorkspace';RawEvidence='Export-WsmRawEvidenceManifest';RegisterTarget='Register-WsmTarget';ToolRelease='Export-WsmToolRelease';SourceResult='Export-WsmSourceStageResult';IdentityMap='Set-WsmIdentityMap';ConfigureMigration='Set-WsmMigrationSpec';ApproveMigration='Approve-WsmMigrationPlan';EstimatePackage='Get-WsmPackageEstimate';ExportPackage='Export-WsmMigrationPackage';CheckPackage='Test-WsmMigrationPackage';RestorePreview='Get-WsmRestorePreview';Restore='Invoke-WsmRestore';FreezeSource='Export-WsmFreezeRecord';ValidationEvidence='Set-WsmValidationEvidence';Validate='Invoke-WsmValidation';CutoverPlan='New-WsmCutoverPlan';Cutover='Invoke-WsmCutover';Acceptance='Get-WsmAcceptanceGates';ExportResult='Export-WsmStageResult';Repair='Repair-WsmOperation';RollbackPreview='Get-WsmRollbackPreview';Rollback='Invoke-WsmRollback';CheckJournal='Test-WsmJournal';PackageZip='Export-WsmPackageZip';ImportPackageZip='Import-WsmPackageZip';MigrationReport='Export-WsmOperationReport'}
